let categories=[];
function categoryNames(){return categories.length?categories.map(c=>c.name):[...new Set(products.map(p=>p.type))];}
function categoryAdmin(){if(usesFatek())return `<p>As categorias acompanham os produtos cadastrados no ERP.</p><div class="category-list">${categories.map(c=>`<article>${esc(c.name)}</article>`).join('')}</div>`;return `<form id="category-form" class="category-create"><label class="field">Nome da categoria<input name="name" required minlength="2" maxlength="60" placeholder="Ex.: Camisas, Jaquetas, Vestidos"></label><button type="submit" class="btn dark">Adicionar categoria</button><p class="form-error" role="alert"></p></form><div class="category-list">${categories.map(c=>`<article><strong>${esc(c.name)}</strong><span>${c.productCount} peça(s)</span></article>`).join('')||'<p>Nenhuma categoria cadastrada.</p>'}</div>`;}
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='category-form')return;e.preventDefault();const button=form.querySelector('button'),error=form.querySelector('.form-error');if(button.disabled)return;button.disabled=true;error.textContent='';try{await api('admin/categories','POST',{name:form.elements.name.value});await route();toast('Categoria cadastrada.');}catch(err){error.textContent=err.message;}finally{button.disabled=false;}});
